ALTER TABLE location
    ADD COLUMN public_slug varchar(120);

ALTER TABLE location
    ADD CONSTRAINT ck_location_public_slug CHECK (
        public_slug IS NULL OR public_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    );

CREATE UNIQUE INDEX uq_location_public_slug
    ON location (public_slug)
    WHERE public_slug IS NOT NULL;

ALTER TABLE menu_product
    ADD COLUMN public_slug varchar(120),
    ADD COLUMN category varchar(80),
    ADD COLUMN artwork_key varchar(40),
    ADD COLUMN display_order integer NOT NULL DEFAULT 0;

ALTER TABLE menu_product
    ADD CONSTRAINT ck_menu_product_public_slug CHECK (
        public_slug IS NULL OR public_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    ),
    ADD CONSTRAINT ck_menu_product_category_not_blank CHECK (
        category IS NULL OR btrim(category) <> ''
    ),
    ADD CONSTRAINT ck_menu_product_artwork_key CHECK (
        artwork_key IS NULL OR artwork_key ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    ),
    ADD CONSTRAINT ck_menu_product_display_order CHECK (display_order >= 0);

CREATE UNIQUE INDEX uq_menu_product_public_slug_organization
    ON menu_product (organization_id, public_slug)
    WHERE public_slug IS NOT NULL;

ALTER TABLE menu_variant
    ADD COLUMN is_default boolean NOT NULL DEFAULT false;

CREATE UNIQUE INDEX uq_menu_variant_default_product
    ON menu_variant (menu_product_id)
    WHERE is_default AND archived_at IS NULL;

